<script setup lang="ts">
import{ref,watch}from'vue';
const props=defineProps<{clinicId:string;kind:string;receivedAt:string;receiptId?:string;modelValue:string[];disabled?:boolean}>(),emit=defineEmits(['update:modelValue']);const items=ref<any[]|null>(null),busy=ref(false),error=ref('');
watch(()=>[props.clinicId,props.kind,props.receivedAt,props.receiptId],()=>{items.value=null;error.value='';emit('update:modelValue',[]);});
async function inspect(){busy.value=true;error.value='';const captured=[props.clinicId,props.kind,props.receivedAt,props.receiptId].join('|');try{if(!props.receivedAt)throw Error('请先填写实际到账时间。');const q=new URLSearchParams({clinicId:props.clinicId,kind:props.kind,receivedAt:props.receivedAt});if(props.receiptId)q.set('receiptId',props.receiptId);const r=await fetch('/api/v1/receipts/adjustments?'+q,{credentials:'same-origin'}),b=await r.json();if(!r.ok)throw Error(b.message||'未取得季度要求。');if(captured!==[props.clinicId,props.kind,props.receivedAt,props.receiptId].join('|'))return;items.value=b.items;emit('update:modelValue',[]);}catch(e){error.value=e instanceof Error?e.message:'查询失败。';}finally{busy.value=false;}}
function choose(id:string,checked:boolean){emit('update:modelValue',checked?[...props.modelValue,id]:props.modelValue.filter(x=>x!==id));}
</script>
<template><div class="rp-box"><button class="b-button outline small" type="button" :disabled="disabled||busy" @click="inspect">{{busy?'正在核对…':'核对原、新到账期间的季度要求'}}</button><p v-if="error" role="alert">{{error}}</p><p v-if="items?.length===0">该诊所的原、新到账期间均未确认，无需选择季度调整轮次。</p><article v-for="q in items||[]" :key="q.quarterId"><strong>{{q.label}}</strong><template v-if="q.canWrite"><p>当前调整事项：{{q.reason}}</p><label class="b-checkbox"><input type="checkbox" :disabled="disabled" :checked="modelValue.includes(q.adjustmentId)" @change="choose(q.adjustmentId,($event.target as HTMLInputElement).checked)"/><span>已核对本次收款事实，明确采用此季度的当前调整轮次。</span></label></template><p v-else>{{q.status==='pending_review'?'已有待复核调整版，须先由总部退回，再补正来源。':'该季度已有确认结果，须先由总部记录针对最新确认版的调整事项。'}}</p></article><p class="b-help">到账时间改变后请重新核对。最终保存会再检查各受影响季度及当前轮次。</p></div></template>
<style scoped>.rp-box{margin:16px 0;padding:16px;border:1px solid #dce7da;border-radius:10px;background:#f5f8f0}.rp-box p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.rp-box article{padding-top:12px;margin-top:12px;border-top:1px solid #dce7da}</style>
